for(const [number,ticket] of assignments) {
  const target=course.modules.flatMap(m=>m.days).find(d=>d.day===number);
  if(!target) throw new Error(`업무 요청 ${ticket.id}의 회차 ${number}가 없습니다.`);
  target.ticket=ticket;
}
